        '我们绕山走。',
      ],
    ),
    'my': LocalizedQuizQuestionText(
      questionText: '"မာယာṃပဗ္ဗတမ်မာ သြရမာမာ။ ဆိုလိုသည်မှာ-',
      options: [
        'တောင်ပေါ်တက်။',
